(6255577, 924682, 96751, '<td valign="top">Just gorgeous.  I love the curving line, and that there is both a reflection, and an area that disappears into the unknown.  A shame about the garbage cans.</td>', 'Just gorgeous.  I love the curving line, and that there is both a reflection, and an area that disappears into the unknown.  A shame about the garbage cans.', '2010-12-16 11:58:08.000000', NULL, 1),
(6255578, 924993, 96751, '<td valign="top">They''re all, ok, got your picture?  Can we go inside now????  Love this image.  The composition is perfect.  Heck, the whole thing is perfect.</td>', 'They''re all, ok, got your picture?  Can we go inside now????  Love this image.  The composition is perfect.  Heck, the whole thing is perfect.', '2010-12-16 11:59:32.000000', NULL, 1),
(6255579, 924860, 96751, '<td valign="top">I actually like this version better than your FTGU entry.</td>', 'I actually like this version better than your FTGU entry.', '2010-12-16 12:00:11.000000', NULL, 1),
(6255582, 925200, 96751, '<td valign="top">Awesome processing!!!!  What a brilliant image.  Although he could also be the walrus :-)  I love the darkness and the soft focus/blur on the figure.</td>', 'Awesome processing!!!!  What a brilliant image.  Although he could also be the walrus :-)  I love the darkness and the soft focus/blur on the figure.', '2010-12-16 12:10:50.000000', NULL, 1),
(6255583, 924609, 96751, '<td valign="top">One of those images I can''t decide if it''s brilliant or horrid.  A successful capture!</td>', 'One of those images I can''t decide if it''s brilliant or horrid.  A successful capture!', '2010-12-16 12:11:36.000000', NULL, 1),
(6255584, 925224, 96751, '<td valign="top">May be one of my favorite Beatles songs.  Interesting, non-romantic photo-interpretation.</td>', 'May be one of my favorite Beatles songs.  Interesting, non-romantic photo-interpretation.', '2010-12-16 12:15:04.000000', NULL, 1),
(6255585, 925220, 96751, '<td valign="top">And the sky is reflecting the fires of hell.</td>', 'And the sky is reflecting the fires of hell.', '2010-12-16 12:15:32.000000', NULL, 1),
(6255589, 924669, 96751, '<td valign="top">You really captured her joy.  I would like to have seen more light on her though, as the background is brighter and draws my eye there.</td>', 'You really captured her joy.  I would like to have seen more light on her though, as the background is brighter and draws my eye there.', '2010-12-16 12:20:56.000000', NULL, 1),
(6255590, 924963, 96751, '<td valign="top">Wonderfully done.  Very clever and well-executed.</td>', 'Wonderfully done.  Very clever and well-executed.', '2010-12-16 12:21:24.000000', NULL, 1),
(6255591, 924321, 96751, '<td valign="top">LOL!  I ALMOST used this line as well.  Brilliant lyrics in this song.  Perfect image for the title.  Or vice versa...</td>', 'LOL!  I ALMOST used this line as well.  Brilliant lyrics in this song.  Perfect image for the title.  Or vice versa...', '2010-12-16 12:22:08.000000', NULL, 1),
