(6255655, 924561, 101707, '<td valign="top">I keep coming back to this image. It seems so true to the essence of the song and challenge. Great work!</td>', 'I keep coming back to this image. It seems so true to the essence of the song and challenge. Great work!', '2010-12-16 14:02:11.000000', NULL, 1),
(6255685, 925201, 30214, '<td valign="top">that would be a fantastic album cover. even the Topaz treatment or HDR, or whatever it is (which I normally dislike) is very fitting. Good job!</td>', 'that would be a fantastic album cover. even the Topaz treatment or HDR, or whatever it is (which I normally dislike) is very fitting. Good job!', '2010-12-16 14:58:52.000000', NULL, 1),
(6255737, 924993, 124346, '<td valign="top">Creo que un encuadre diferente no estaria mal, eliminar todo el blanco de la parte inferior y hacer una imagen alargada a lo ancho, simplemente otra idea.  Pero en general es agradable la foto.</td>', 'Creo que un encuadre diferente no estaria mal, eliminar todo el blanco de la parte inferior y hacer una imagen alargada a lo ancho, simplemente otra idea.  Pero en general es agradable la foto.', '2010-12-16 16:18:04.000000', NULL, 1),
(6255741, 924512, 124346, '<td valign="top">La pose del sujeto es genial, no se si la logro saltando, pero si fue asi consiguio darle un efecto tan real como si estuviera flotando, no se ve como si saltara.  El entorno tambien esta muy bien.  Excelente foto.</td>', 'La pose del sujeto es genial, no se si la logro saltando, pero si fue asi consiguio darle un efecto tan real como si estuviera flotando, no se ve como si saltara.  El entorno tambien esta muy bien.  Excelente foto.', '2010-12-16 16:20:44.000000', NULL, 1),
(6255743, 925022, 124346, '<td valign="top">Me gustaria que el carro estuviera un poco mas iluminado, verlo un poco mas.  Muy bello el atardecer.</td>', 'Me gustaria que el carro estuviera un poco mas iluminado, verlo un poco mas.  Muy bello el atardecer.', '2010-12-16 16:21:42.000000', NULL, 1),
(6255745, 925028, 124346, '<td valign="top">Quizas a otra hora del dia la iluminacion podria ayudar a este encuadre a resaltar la casa, que a mi parecer es algo importante en la composicion.</td>', 'Quizas a otra hora del dia la iluminacion podria ayudar a este encuadre a resaltar la casa, que a mi parecer es algo importante en la composicion.', '2010-12-16 16:25:02.000000', NULL, 1),
(6255746, 924312, 124346, '<td valign="top">Un enfoque mejor podria mejorar la imagen.  Me gusta el efecto de movimiento en las manos.</td>', 'Un enfoque mejor podria mejorar la imagen.  Me gusta el efecto de movimiento en las manos.', '2010-12-16 16:27:22.000000', NULL, 1),
(6255747, 925156, 124346, '<td valign="top">Falta algo de luz.</td>', 'Falta algo de luz.', '2010-12-16 16:28:03.000000', NULL, 1),
