(6256017, 924522, 96751, '<td valign="top">Incredibly terrifying.  What an awesome image.</td>', 'Incredibly terrifying.  What an awesome image.', '2010-12-17 00:23:38.000000', NULL, 1),
(6256018, 925201, 96751, '<td valign="top">AWESOME!!   I can''t stand how fantastic this is.  Seriously!!!<br/> <br/>*runs about trying to calm down*<br/> <br/>It''s just such a perfectly beautiful, incongruous, heavenly LSD image.  Front page for me.</td>', 'AWESOME!!   I can''t stand how fantastic this is.  Seriously!!! *runs about trying to calm down* It''s just such a perfectly beautiful, incongruous, heavenly LSD image.  Front page for me.', '2010-12-17 00:23:56.000000', NULL, 1),
