(6256020, 924760, 96751, '<td valign="top">So sweet.  Looks like they''ve got a long way to go before "old".</td>', 'So sweet.  Looks like they''ve got a long way to go before "old".', '2010-12-17 00:25:30.000000', NULL, 1),
(6256021, 925242, 96751, '<td valign="top">Oh wow.  This is really strange.  And sad, and weird, and really pisses me off.  Well done.</td>', 'Oh wow.  This is really strange.  And sad, and weird, and really pisses me off.  Well done.', '2010-12-17 00:26:21.000000', NULL, 1),
